  position: relative;
  min-height: 300px;
  padding: 0;
}
.magiclink__wrapper .inner-content {
  background-color: #ffffff;
  padding: 16px 24px;
}
.magiclink__wrapper .icon-inbox {
  height: 60px;
}
.magiclink__wrapper .icon-inbox > div {
  background-color: #fff;
}
.magiclink__wrapper .resending {
  color: #00b16a;
}
.magiclink__wrapper .resending.error {
  color: #d9202c;
}
.magiclink__wrapper .header {
  background-color: #e1e1e1;
  height: 48px;
  color: #888;
  font-size: 14px;
  border-radius: 2px 2px 0 0;
  font-weight: 400;
  border: 1px solid rgb(241, 241, 241);
  display: flex;
}
.magiclink__wrapper .header .header-content {
  display: flex;
  margin-left: 16px;
  width: 100%;
}
.magiclink__wrapper .header .header-content a {
  font-size: 16px;
  color: #888888;
  text-decoration: none;
  display: flex;
  align-items: center;
}
.magiclink__wrapper .header .header-content a:hover {
  text-decoration: underline;
}
.magiclink__wrapper .header .header-content a span {
  margin-left: 2px;
}
.magiclink__wrapper .magiclink__footer {
  margin-top: 36px;
}
.magiclink__wrapper .magiclink__footer .resending {
  color: #00b16a;
}
.magiclink__wrapper .magiclink__footer .resending.error {
  color: #d9202c;
